  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `creator` varchar(64) DEFAULT '',
  `updater` varchar(64) DEFAULT '',
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `id` bigint NOT NULL AUTO_INCREMENT,
  `no` text,
  `status` int DEFAULT 0,
  `customer_id` bigint DEFAULT 0,
  `account_id` bigint DEFAULT 0,
  `sale_user_id` bigint DEFAULT 0,
  `out_time` datetime DEFAULT NULL,
  `order_id` bigint DEFAULT 0,
  `order_no` varchar(255) DEFAULT NULL,
  `total_count` decimal(24,8) DEFAULT 0,
  `total_price` decimal(24,8) DEFAULT 0,
  `receipt_price` decimal(24,8) DEFAULT 0,
  `total_product_price` decimal(24,8) DEFAULT 0,
  `total_tax_price` decimal(24,8) DEFAULT 0,
  `discount_percent` decimal(24,8) DEFAULT 0,
  `discount_price` decimal(24,8) DEFAULT 0,
  `other_price` decimal(24,8) DEFAULT 0,
  `file_url` text,
  `remark` text,
  `tenant_id` bigint NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `idx_customer_id` (`customer_id`),
  KEY `idx_account_id` (`account_id`),
  KEY `idx_sale_user_id` (`sale_user_id`),
  KEY `idx_order_id` (`order_id`),
  KEY `idx_tenant_id` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

